template.css:
html, body {
  margin: 0;
  padding: 0;
  font-family: Arial, Helvetica, sans-serif;
  color: #000;
}
.label {
  box-sizing: border-box;
  width: 100mm;
  height: 50mm;
  padding: 3mm 3.5mm 2.4mm;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 3mm;
}
.name {
  font-size: 16px;
  font-weight: 700;
  line-height: 1.2;
  max-height: 2.4em;
  overflow: hidden;
  flex: 1 1 auto;
  min-width: 0;
}
.category {
  font-size: 11px;
  font-weight: 600;
  color: #444;
  flex: 0 0 auto;
  white-space: nowrap;
}
.price {
  font-size: 30px;
  font-weight: 800;
  margin-top: 1.6mm;
  line-height: 1;
  letter-spacing: -0.02em;
}
.currency {
  font-size: 14px;
  font-weight: 700;
  margin-left: 1.2mm;
}
.meta {
  font-size: 10px;
  margin-top: 1mm;
  color: #444;
}
.barcode-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.55mm;
  margin-top: auto;
  width: 100%;
}
img.barcode {
  height: 16mm;
  width: 100%;
  max-width: 100%;
  object-fit: contain;
  object-position: center bottom;
}
.code {
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-align: center;
  white-space: nowrap;
}
